package com.ferreteriahuaman.repository;
import com.ferreteriahuaman.dto.CashModels.*;import com.ferreteriahuaman.dto.CatalogModels.Page;import java.sql.*;import java.time.*;import java.util.*;
import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository @Profile("db") public class CashRepository {
 private final JdbcTemplate jdbc;public CashRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private static final String SELECT="select c.id_caja,c.fecha,c.estado_caja,c.monto_inicial,a.username apertura,z.username cierre,c.feccre,c.fecha_cierre,c.obs_apertura,c.obs_cierre,c.efectivo_contado,c.yape_reportado,c.debito_reportado,c.diferencia_efectivo,c.diferencia_yape,c.diferencia_debito,coalesce(c.efectivo_esperado,(select coalesce(sum(case when sentido='I' then importe else -importe end),0) from huaman.movimiento_caja where id_caja=c.id_caja and medio='EFECTIVO')) efectivo,coalesce(c.yape_esperado,(select coalesce(sum(case when sentido='I' then importe else -importe end),0) from huaman.movimiento_caja where id_caja=c.id_caja and medio='YAPE')) yape,coalesce(c.debito_esperado,(select coalesce(sum(case when sentido='I' then importe else -importe end),0) from huaman.movimiento_caja where id_caja=c.id_caja and medio='DEBITO')) debito,(select count(*) from huaman.venta where id_caja=c.id_caja and estado='A' and estado_venta='BORRADOR' and total>0) pendientes from huaman.caja_diaria c join huaman.usuario a on a.id_usuario=c.id_usuario_apertura left join huaman.usuario z on z.id_usuario=c.id_usuario_cierre ";
 private String money(ResultSet r,String field)throws SQLException{var v=r.getBigDecimal(field);return v==null?null:v.toPlainString();}
 private Register row(ResultSet r,int n)throws SQLException{return new Register(r.getLong("id_caja"),r.getObject("fecha",LocalDate.class),r.getString("estado_caja"),money(r,"monto_inicial"),r.getString("apertura"),r.getString("cierre"),r.getObject("feccre",LocalDateTime.class),r.getObject("fecha_cierre",LocalDateTime.class),r.getString("obs_apertura"),r.getString("obs_cierre"),money(r,"efectivo"),money(r,"yape"),money(r,"debito"),money(r,"efectivo_contado"),money(r,"yape_reportado"),money(r,"debito_reportado"),money(r,"diferencia_efectivo"),money(r,"diferencia_yape"),money(r,"diferencia_debito"),r.getLong("pendientes"));}
 public Current current(){var date=jdbc.queryForObject("select timezone('America/Lima',now())::date",LocalDate.class);return new Current(date,jdbc.query(SELECT+"where c.estado='A' and (c.estado_caja='ABIERTA' or c.fecha=?) order by (c.estado_caja='ABIERTA') desc,c.fecha desc limit 1",this::row,date).stream().findFirst().orElse(null));}
 public Optional<Register> get(long id){return jdbc.query(SELECT+"where c.id_caja=? and c.estado='A'",this::row,id).stream().findFirst();}
 public Page<Register> history(LocalDate start,LocalDate end,String state,int page,int size){String filter=" where c.estado='A' and (?::date is null or c.fecha>=?) and (?::date is null or c.fecha<=?) and (?='' or c.estado_caja=?)";Object[] args={start,start,end,end,state,state};long count=jdbc.queryForObject("select count(*) from huaman.caja_diaria c"+filter,Long.class,args);var params=new ArrayList<>(Arrays.asList(args));params.add(size);params.add((long)page*size);return new Page<>(jdbc.query(SELECT+filter+" order by c.fecha desc,c.id_caja desc limit ? offset ?",this::row,params.toArray()),count,page,size);}
 public Page<Movement> movements(long id,int page,int size){long count=jdbc.queryForObject("select count(*) from huaman.movimiento_caja where id_caja=?",Long.class,id);return new Page<>(jdbc.query("select id_movimiento_caja,tipo_movimiento,medio,sentido,importe,motivo,feccre,usucre,id_venta from huaman.movimiento_caja where id_caja=? order by id_movimiento_caja desc limit ? offset ?",(r,n)->new Movement(r.getLong("id_movimiento_caja"),r.getString("tipo_movimiento"),r.getString("medio"),r.getString("sentido"),money(r,"importe"),r.getString("motivo"),r.getObject("feccre",LocalDateTime.class),r.getString("usucre"),r.getObject("id_venta",Long.class)),id,size,(long)page*size),count,page,size);}
 public long open(Open i){return jdbc.queryForObject("select huaman.abrir_caja(?,?,?)",Long.class,i.fondo(),i.clave(),i.observacion());}
 public long manual(long id,Manual i){return jdbc.queryForObject("select huaman.registrar_movimiento_caja(?,?,?,?,?)",Long.class,id,i.tipo(),i.importe(),i.motivo(),i.clave());}
 public long close(long id,Close i){return jdbc.queryForObject("select huaman.cerrar_caja(?,?,?,?,?,?)",Long.class,id,i.efectivo(),i.yape(),i.debito(),i.observacion(),i.clave());}
}
